1. Create a `TooltipContext.js` file and define the context.

```jsx
import React, { createContext, useContext, useState } from 'react';

const TooltipContext = createContext();

export const TooltipProvider = ({ children }) => {
  const [activeTooltip, setActiveTooltip] = useState(null);

  const closeTooltip = () => {
    setActiveTooltip(null);
  };

  const openTooltip = (tooltipContent) => {
    setActiveTooltip(tooltipContent);
  };

  return (
    <TooltipContext.Provider value={{ closeTooltip, openTooltip, activeTooltip }}>
      {children}
    </TooltipContext.Provider>
  );
};

export const useTooltip = () => useContext(TooltipContext);
```

2. Create a `Tooltip.js` file for the Tooltip component.

```jsx
import React, { useEffect, useState } from 'react';
import { useTooltip } from './TooltipContext';

const Tooltip = ({ children, placement = 'bottom' }) => {
  const [tooltipOpen, setTooltipOpen] = useState(false);
  const { activeTooltip, closeTooltip, openTooltip } = useTooltip();

  const handleMouseEnter = () => {
    if (activeTooltip !== children) {
      openTooltip(children);
    }
    setTooltipOpen(true);
  };

  const handleMouseLeave = () => {
    if (activeTooltip === children) {
      closeTooltip();
    }
    setTooltipOpen(false);
  };

  useEffect(() => {
    if (tooltipOpen) {
      document.addEventListener('click', closeTooltip);
    }

    return () => {
      document.removeEventListener('click', closeTooltip);
    };
  }, [tooltipOpen]);

  return (
    <div>
      <div onMouseEnter={handleMouseEnter} onMouseLeave={handleMouseLeave}>
        {children}
      </div>
      {tooltipOpen && (
        <div
          className={`tooltip ${placement}`}
          style={{ top: `${tooltipOpen.getBoundingClientRect().bottom + 10}px`, left: `${tooltipOpen.getBoundingClientRect().left}px` }}
        >
          {activeTooltip}
        </div>
      )}
    </div>
  );
};

export default Tooltip;
```

