Here's a JavaScript implementation for packing and unpacking an array of entities into an ArrayBuffer. The entities have the following fields: `id` (4 bits) and `size` (3 bits).

```javascript
function packEntities(entities) {
  const buffer = new ArrayBuffer(entities.length);
  const view = new DataView(buffer);

  for (let i = 0; i < entities.length; i++) {
    const entity = entities[i];
    const id = entity.id & 0xF; // Masking to get the 4 least significant bits
    const size = entity.size & 0x7; // Masking to get the 3 least significant bits

    view.setUint8(i * (id + size), id);
    view.setUint8(i * (id + size) + 1, size);

    // Set the remaining bits of the byte for the id and size fields
    if (i * (id + size) < buffer.byteLength - 1) {
      view.setUint8(i * (id + size) + 2, entity.id >> 4 | entity.size << 5);
    }
  }

  return buffer;
}

function unpackEntities(buffer, length) {
  const entities = [];
  const view = new DataView(buffer);

  for (let i = 0; i < length; i++) {
    const idByte = view.getUint8(i);
    const sizeByte = view.getUint8(i + 1);

    const id = idByte & 0xF; // Masking to get the 4 least significant bits
    const size = sizeByte & 0x7; // Masking to get the 3 least significant bits

    const entitySize = id + size + 2; // 2 extra bits for id and size
    const entityData = new Uint8Array(buffer, i, entitySize);

    entities.push({
      id: id | (entityData[0] >> 4 & 0xF0),
      size: size | (entityData[0] << 5 & 0x70) | (entityData[1] >> 3)
    });

    i += entitySize - 1; // Move to the next entity's starting position
  }

  return entities;
}
```

You can use these functions like this:

```javascript
const entities = [
  { id: 1, size: 2 },
  { id: 3, size: 1 },
  { id: 5, size: 3 }
];

const buffer = packEntities(entities);
const unpackedEntities = unpackEntities(buffer, buffer.byteLength);

console.log(unpackedEntities); // [ { id: 1, size: 2 }, { id: 3, size: 1 }, { id: 5, size: 3 } ]
```

