// app/services/csv-downloader.ts
import { inject as service } from '@ember/service';
import { A } from '@ember/array';
import { task, timeout } from 'ember-concurrency';
import { computed } from '@ember/object';
import { read } from 'ember-cli-htmlbars';
import { WebWorker } from 'ember-cli-web-worker';

export default class CsvDownloaderService {
  @service('store') store;

  // Define the web worker
  worker = new WebWorker(
    new URL('assets/csv-downloader.js', import.meta.url)
  );

  // Define the CSV data to be downloaded
  data = A([]);

  // Define the CSV filename
  filename = 'export.csv';

  // Define the CSV headers
  headers = A([]);

  // Define the CSV download task
  downloadCSV = task(function* () {
    yield timeout(500);
    const csvData = this.generateCSVData();
    this.worker.postMessage({ csvData, filename: this.filename });
  }).restartable();

  // Define the CSV data generation method
  generateCSVData() {
    const headers = this.headers.map((header) => header.label);
    const rows = this.data.map((row) => {
      return headers.map((header) => {
        const field = read(row, header.property);
        return field ? field.value : '';
      });
    });

    return [headers, ...rows].flat().join(',');
  }

  // Define the computed property for the CSV headers
  get computedHeaders() {
    return this.store.query('model', { filter: {} }).then((models) => {
      return models.map((model) => {
        return {
          label: model.name.pluralize(),
          property: model.name,
        };
      });
    });
  }

  // Start the CSV download task when the service is initialized
  init() {
    super.init(...arguments);
    this.data = this.store.findAll('model');
    this.headers = this.computedHeaders;
    this.downloadCSV.perform();
  }
}
