To compare two Excel files and show discrepancies in Node.js, you can use a library like `xlsx` to read the Excel files and `lodash` for comparison. Here's a basic example:

First, install the necessary dependencies:

```bash
npm install xlsx lodash
```

Then, create a script (e.g., `compareExcel.js`) to compare the files:

```javascript
const XLSX = require('xlsx');
const _ = require('lodash');

function compareFiles(file1, file2, sheetName) {
  const workbook1 = XLSX.readFile(file1);
  const workbook2 = XLSX.readFile(file2);

  const sheet1 = workbook1.Sheets[sheetName];
  const sheet2 = workbook2.Sheets[sheetName];

  const keys1 = _.keys(sheet1);
  const keys2 = _.keys(sheet2);

  const commonKeys = _.intersection(keys1, keys2);

  const differences = [];

  commonKeys.forEach((key) => {
    if (sheet1[key].v !== sheet2[key].v) {
      differences.push({
        key,
        file1: sheet1[key].v,
        file2: sheet2[key].v,
      });
    }
  });

  console.log(differences);
}

compareFiles('file1.xlsx', 'file2.xlsx', 'Sheet1');
```

This script reads the specified sheets from the provided Excel files, finds the common keys, and checks if the values for those keys are the same in both files. If there's a difference, it logs the key, the value from the first file, and the value from the second file.

Replace `'file1.xlsx'`, `'file2.xlsx'`, and `'Sheet1'` with the paths to your Excel files and the names of the sheets you want to compare.

